mapper.insert:
INSERT INTO t_order (order_no, buyer_id, seller_id, total_amount, status, remark, delivery_method, address
    , seller_payment_config_id
    , create_time, update_time, deleted, version)
VALUES (#{orderNo}, #{buyerId}, #{sellerId}, #{totalAmount}, #{status}, #{remark}, #{deliveryMethod}, #{address}
    , #{sellerPaymentConfigId}
    , NOW(), NOW(), 0, 0)

mapper.update:
UPDATE t_order
total_amount = #{totalAmount}, status = #{status}, pay_time = #{payTime}, ship_time = #{shipTime}, finish_time = #{finishTime}, cancel_time = #{cancelTime}, cancel_reason = #{cancelReason}, delivery_method = #{deliveryMethod}, address = #{address}, tracking_no = #{trackingNo}, trade_no = #{tradeNo}, pre_refund_status = #{preRefundStatus}, version = version + 1
WHERE id = #{id} AND deleted = 0 AND version = #{version}

